// Builds the example images in docs/images from the files in examples/ and a
// small made-up GitHub snapshot. Nothing here is real data: the repositories,
// commits and releases are samples, and the snapshot is generated by a fixed
// rule, so running this twice gives the same files.
//
//   pnpm build && node scripts/build-example-images.mjs

import { execFileSync } from "node:child_process";
import { cp, mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const cli = path.join(root, "dist", "index.js");
const out = path.join(root, "docs", "images");
const FETCHED = "2026-11-08";
const OWNER = "your-github-username";

// A tiny deterministic generator, so the sample commits never change.
function sequence(seed) {
  let state = seed;
  return () => {
    state = (state * 1664525 + 1013904223) % 4294967296;
    return state / 4294967296;
  };
}

function addDays(day, amount) {
  const date = new Date(`${day}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + amount);
  return date.toISOString().slice(0, 10);
}

function commitWeeks(seed, busy) {
  const next = sequence(seed);
  return Array.from({ length: 52 }, (_, index) => ({
    weekStart: addDays(FETCHED, -7 * (51 - index)),
    days: Array.from({ length: 7 }, (_unused, day) => {
      const roll = next();
      const weekday = day > 0 && day < 6;
      return roll < (weekday ? 0.55 : 0.8) ? 0 : Math.ceil(next() * busy);
    }),
  }));
}

const SAMPLE = [
  [
    "example-app",
    "TypeScript",
    142,
    18,
    5,
    "v2.3.0",
    "2026-10-21",
    6,
    [
      ["TypeScript", 84000],
      ["CSS", 9000],
      ["HTML", 3000],
    ],
  ],
  [
    "api-toolkit",
    "Go",
    87,
    9,
    4,
    "v1.8.2",
    "2026-09-30",
    4,
    [
      ["Go", 61000],
      ["Shell", 2000],
    ],
  ],
  [
    "data-notebooks",
    "Python",
    53,
    6,
    3,
    "v0.4.0",
    "2026-08-12",
    3,
    [
      ["Python", 38000],
      ["Jupyter Notebook", 22000],
    ],
  ],
  [
    "design-tokens",
    "JavaScript",
    31,
    4,
    2,
    "v1.1.0",
    "2026-06-02",
    2,
    [
      ["JavaScript", 17000],
      ["CSS", 6000],
    ],
  ],
  ["cli-playground", "Rust", 24, 2, 3, "v0.2.1", "2026-04-18", 3, [["Rust", 29000]]],
  ["learning-log", "Markdown", 9, 1, 1, undefined, undefined, 1, [["Markdown", 12000]]],
];

function sampleSnapshot() {
  return {
    version: 1,
    source: "GitHub REST API",
    username: OWNER,
    fetchedAt: `${FETCHED}T12:00:00.000Z`,
    repositories: SAMPLE.map(
      ([name, language, stars, forks, , tag, published, busy, languages], index) => ({
        fullName: `${OWNER}/${name}`,
        name,
        url: `https://github.com/${OWNER}/${name}`,
        language,
        stars,
        forks,
        archived: false,
        fork: false,
        createdAt: "2025-02-01T00:00:00Z",
        pushedAt: `2026-11-0${String(7 - index)}T10:00:00Z`,
        ...(tag === undefined
          ? {}
          : { latestRelease: { tagName: tag, publishedAt: `${published}T10:00:00Z` } }),
        languages: languages.map(([languageName, bytes]) => ({ name: languageName, bytes })),
        commitActivity: commitWeeks(1000 + index * 17, busy),
        provenance: "OBSERVED",
      }),
    ),
  };
}

// [target, example file, data file, theme, output name]
const IMAGES = [
  ["startup", "startup-dashboard.json", "startup.json", "TERMINAL", "startup-terminal.svg"],
  ["startup", "startup-dashboard.json", "startup.json", "LIGHT", "startup-light.svg"],
  ["ai", "ai-engineering-dashboard.json", "ai-engineering.json", "TERMINAL", "ai-terminal.svg"],
  ["ai", "ai-engineering-dashboard.json", "ai-engineering.json", "MIDNIGHT", "ai-midnight.svg"],
  [
    "activity",
    "developer-activity.json",
    "developer-activity.json",
    "TERMINAL",
    "activity-terminal.svg",
  ],
  ["activity", "developer-activity.json", "developer-activity.json", "DARK", "activity-dark.svg"],
];

const work = await mkdtemp(path.join(os.tmpdir(), "devtrace-gallery-"));
try {
  await mkdir(path.join(work, "data"), { recursive: true });
  for (const file of new Set(IMAGES.map((image) => image[2]))) {
    const source = IMAGES.find((image) => image[2] === file)[1];
    await cp(path.join(root, "examples", source), path.join(work, "data", file));
  }
  await writeFile(
    path.join(work, "data", "github-snapshot.json"),
    `${JSON.stringify(sampleSnapshot(), null, 2)}\n`,
  );
  await mkdir(out, { recursive: true });
  for (const [target, , , theme, name] of IMAGES) {
    execFileSync(process.execPath, [cli, "generate", target, "--theme", theme, "--output", name], {
      cwd: work,
      stdio: ["ignore", "ignore", "inherit"],
    });
    const svg = await readFile(path.join(work, "public", "indicators", name), "utf8");
    await writeFile(path.join(out, name), svg);
    console.log(`docs/images/${name}`);
  }
} finally {
  await rm(work, { recursive: true, force: true });
}
